/* input */
input[type=text]::-ms-clear {
  display: none;
}

input[type=text], input[type=password], textarea {
  width: 100%;
  height: 48px;
  padding: 0 16px;
  font-size: 1.6rem;
  font-family: "nanumsquare";
  border: 1px solid #a6a6a6;
  border-radius: 0;
  -webkit-appearance: none;
}

textarea {
  padding: 20px 16px;
  line-height: 32px;
  height: auto;
}

textarea::-webkit-input-placeholder {
  font-size: 1.6rem;
}

textarea:-ms-input-placeholder {
  font-size: 1.6rem;
}

input[type=checkbox] {
  position: absolute;
  width: 22px;
  height: 23px;
  opacity: 0;
}

input[type=checkbox] + label {
  font-size: 1.4rem;
  line-height: 22px;
  font-weight: bold;
  position: relative;
  display: inline-block;
  padding: 0 0 0 38px;
  overflow: hidden;
}

input[type=checkbox] + label .icon {
  width: 20px;
  height: 20px;
  display: inline-block;
  position: absolute;
  top: 1px;
  left: 0;
  margin: 0;
  border: 1px solid #000;
  border-radius: 0;
  background: #fff;
}

input[type=checkbox]:checked + label .icon {
  background: #fff url(https://image.samsungsds.com/resource/kr/images/icon/ico_ck.png?queryString=20260714085954) no-repeat 50% 50%;
}

.check_msg.type1.sync.separate_tnc input[type=checkbox] + label .icon {
  outline: none;
}

.check_msg.type1.sync.separate_tnc input[type=checkbox]:checked + label .icon {
  border-color: #0a78ea;
  background: #0a78ea url(https://image.samsungsds.com/resource/kr/images/icon/ico_ck_white.png) no-repeat 50% 50%;
}

.check_msg.type1.sync.separate_tnc input[type=checkbox]:checked:focus + label .icon,
.check_msg.type1.sync.separate_tnc input[type=checkbox]:focus-visible + label .icon {
  outline: 0.1rem dotted #000;
  outline: -webkit-focus-ring-color auto 0.5rem;
}

input[type=checkbox] + label.error .icon {
  border-color: #ff0000 !important;
}

input[type=checkbox]:disabled + label .icon {
  border-color: #c2c2c2 !important;
  background: 0 !important;
}

input[type=radio] {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

input[type=radio] + label {
  font-size: 1.4rem;
  line-height: 22px;
  font-weight: bold;
  position: relative;
  display: inline-block;
  padding: 0 0 0 38px;
  overflow: hidden;
}

input[type=radio] + label .icon {
  width: 20px;
  height: 20px;
  display: inline-block;
  position: absolute;
  top: 1px;
  left: 0;
  margin: 0 0 0 0;
  border: 1px solid #aaa;
  background-color: #fff;
  border-radius: 10px;
}

input[type=radio]:checked + label .icon:before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  margin: -5px 0 0 -5px;
  width: 10px;
  height: 10px;
  background: url(https://image.samsungsds.com/resource/kr/images/icon/ico_radio.png?queryString=20201124022056) no-repeat 50% 50%;
  background-size: 10px;
}

input[type=radio]:checked + label .icon.is-gray:before {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%;
  margin: -5px 0 0 -5px;
  width: 10px;
  height: 10px;
  background: url(https://image.samsungsds.com/resource/kr/images/icon/ico_radio_2.png?queryString=20201124022056) no-repeat 50% 50%;
  background-size: 10px;
}

