.list_support_useful .ico_comm {
  position: absolute;
  top: 50%;
  right: 3rem;
  width: 2.8rem;
  height: 1.8rem;
  margin-top: -0.85rem;
  -webkit-transition: all 0.3s;
  -moz-transition: all 0.3s;
  transition: all 0.3s;
}

.list_support_useful a.ico_comm:hover {
  right: 2.7rem;
}

.list_support_useful span.ico_comm {
  pointer-events: none;
}

.list_support_useful .ico_comm .ico_arrow {
  position: absolute;
  right: 0;
  top: 50%;
}

.list_support_useful .ico_arrow {
  display: inline-block;
  width: 2.5rem;
  height: 0.2rem;
  background-color: #000;
}

.list_support_useful .ico_arrow:before {
  display: block;
  position: absolute;
  right: 0.2rem;
  top: -0.5rem;
  width: 1.2rem;
  height: 1.2rem;
  border: solid #000;
  border-width: 0.2rem 0.2rem 0 0;
  -webkit-transform: rotate(45deg);
  -ms-transform: rotate(45deg);
  -moz-transform: rotate(45deg);
  -o-transform: rotate(45deg);
  transform: rotate(45deg);
  content: "";
}

